"""a module for unittest
"""
import os
import threading

from testbase.conf import settings


class _NotExistedItem(object):
    pass


# Serialize seal transitions. Bypass is thread-local so one test can update
# settings without opening a window where other threads observe them as writable.
_settings_update_lock = threading.RLock()
_settings_tls = threading.local()


def _private_get(obj, name, default=None):
    try:
        return object.__getattribute__(obj, name)
    except AttributeError:
        return default


def _private_set(obj, name, value):
    object.__setattr__(obj, name, value)


def _install_settings_write_guard():
    """Make runtime settings assignments fail closed.

    Loading used to be lazy and the sealed flag was also cleared by
    ``modify_settings`` and never restored. ``Settings.__setattr__`` therefore
    accepted writes whenever nothing earlier in the process had loaded or
    re-sealed configuration. After the first ensure/load, assignments always
    see a sealed object unless this module is inside a settings update.
    """
    cls = type(settings)
    if _private_get(cls, "_settings_write_guard_installed", False):
        return

    orig_setattr = cls.__setattr__
    orig_delattr = cls.__delattr__
    orig_ensure = cls._Settings__ensure_loaded

    def safe_ensure(self):
        if _private_get(self, "_Settings__guard_loaded", False):
            return
        # Already inside ensure_loaded on this thread (setattr during load).
        if _private_get(self, "_Settings__ensuring", False):
            return
        with _settings_update_lock:
            if _private_get(self, "_Settings__guard_loaded", False) or _private_get(
                self, "_Settings__ensuring", False
            ):
                return
            _private_set(self, "_Settings__ensuring", True)
            _settings_tls.bypass = True
            try:
                return orig_ensure(self)
            finally:
                _settings_tls.bypass = False
                _private_set(self, "_Settings__ensuring", False)
                # Sticky: a later unseal must not make ensure_loaded reload
                # and must not leave settings writable.
                _private_set(self, "_Settings__guard_loaded", True)
                _private_set(self, "_Settings__sealed", True)

    def _sealed(self):
        return bool(_private_get(self, "_Settings__sealed", False))

    def guarded_setattr(self, name, value):
        if isinstance(name, str) and name.startswith("_Settings__"):
            return orig_setattr(self, name, value)
        if getattr(_settings_tls, "bypass", False):
            return orig_setattr(self, name, value)
        with _settings_update_lock:
            if getattr(_settings_tls, "bypass", False):
                return orig_setattr(self, name, value)
            safe_ensure(self)
            if _sealed(self):
                raise RuntimeError("settings has been sealed, cannot set %s" % name)
            return orig_setattr(self, name, value)

    def guarded_delattr(self, name):
        if isinstance(name, str) and name.startswith("_Settings__"):
            return orig_delattr(self, name)
        if getattr(_settings_tls, "bypass", False):
            return orig_delattr(self, name)
        with _settings_update_lock:
            if getattr(_settings_tls, "bypass", False):
                return orig_delattr(self, name)
            safe_ensure(self)
            if _sealed(self):
                raise RuntimeError(
                    "settings has been sealed, cannot delete %s" % name
                )
            return orig_delattr(self, name)

    cls._Settings__ensure_loaded = safe_ensure
    cls.__setattr__ = guarded_setattr
    cls.__delattr__ = guarded_delattr
    type.__setattr__(cls, "_settings_write_guard_installed", True)


_install_settings_write_guard()


