import os
import threading

from testbase.conf import settings


class _NotExistedItem(object):
    pass


# Writes are process-global. Serialize seal changes so one test cannot observe
# settings as writable just because another thread is inside modify_settings.
_settings_lock = threading.RLock()
_settings_tls = threading.local()
_settings_sealed_once = set()


def _raw_get(obj, name, default=None):
    try:
        return object.__getattribute__(obj, name)
    except AttributeError:
        return default


def _install_settings_seal_guard():
    """Make runtime assignment fail closed.

    Settings stay unsealed until the first lazy load, and ``__setattr__`` does
    not load. A write that happens before any read is therefore stored instead
    of rejected, which is why the failure depended on what had already run in
    this process. ``modify_settings`` must still be able to publish its
    temporary values, so an explicit unseal after the first load is honored.
    """
    if getattr(_install_settings_seal_guard, "done", False):
        return

    cls = type(settings)
    orig_setattr = cls.__setattr__
    orig_ensure = cls._Settings__ensure_loaded

    def ensure_loaded(self):
        # Re-entered from __getattribute__/__setattr__ while orig_ensure runs.
        if getattr(_settings_tls, "depth", 0):
            return
        if id(self) in _settings_sealed_once:
            return
        with _settings_lock:
            if getattr(_settings_tls, "depth", 0) or id(self) in _settings_sealed_once:
                return
            _settings_tls.depth = 1
            try:
                result = orig_ensure(self)
            finally:
                _settings_tls.depth = 0
            # Load is supposed to seal. If this build left the flag clear,
            # seal here so the following __setattr__ takes the read-only path.
            if not _raw_get(self, "_Settings__sealed", False):
                object.__setattr__(self, "_Settings__sealed", True)
            _settings_sealed_once.add(id(self))
            return result

    def guarded_setattr(self, name, value):
        if isinstance(name, str) and name.startswith("_Settings__"):
            return orig_setattr(self, name, value)
        if getattr(_settings_tls, "bypass", False) or getattr(_settings_tls, "depth", 0):
            return orig_setattr(self, name, value)
        with _settings_lock:
            if getattr(_settings_tls, "bypass", False) or getattr(
                _settings_tls, "depth", 0
            ):
                return orig_setattr(self, name, value)
            ensure_loaded(self)
            # Delegate so the original error type and message are preserved.
            return orig_setattr(self, name, value)

    cls._Settings__ensure_loaded = ensure_loaded
    cls.__setattr__ = guarded_setattr
    _install_settings_seal_guard.done = True


_install_settings_seal_guard()


