"""a module for unittest
"""
import os
import threading

from testbase.conf import settings


class _NotExistedItem(object):
    pass


# Settings are a process-wide singleton. Loading is lazy and the seal flag is
# also the only thing that makes assignment fail, so a write before the first
# read was stored, and modify_settings used to leave the flag cleared. Either
# way later tests saw a different object than earlier ones.
_settings_lock = threading.RLock()
_settings_tls = threading.local()
_settings_prepared = set()


def _is_private(name):
    return isinstance(name, str) and (
        name.startswith("_Settings__") or (name.startswith("__") and name.endswith("__"))
    )


def _is_sealed(obj):
    try:
        return bool(object.__getattribute__(obj, "_Settings__sealed"))
    except AttributeError:
        return False


def _install_settings_write_guard():
    cls = type(settings)
    if getattr(cls, "_settings_write_guard_installed", False):
        return

    orig_setattr = cls.__setattr__
    orig_delattr = cls.__delattr__
    orig_ensure = cls._Settings__ensure_loaded

    def ensure_loaded(self):
        # Already loaded, or re-entered from the load itself.
        if id(self) in _settings_prepared or getattr(_settings_tls, "in_load", False):
            return
        _settings_tls.in_load = True
        previous_bypass = getattr(_settings_tls, "bypass", False)
        _settings_tls.bypass = True
        try:
            result = orig_ensure(self)
        finally:
            _settings_tls.in_load = False
            _settings_tls.bypass = previous_bypass
        _settings_prepared.add(id(self))
        # Some builds never seal if nothing has been read yet.
        if not _is_sealed(self):
            object.__setattr__(self, "_Settings__sealed", True)
        return result

    def _reject_set(self, name, value):
        """Raise the original seal error when one exists; otherwise reject."""
        try:
            had_old = True
            old_value = getattr(self, name)
        except Exception:
            had_old = False
            old_value = None
        try:
            return orig_setattr(self, name, value)
        except Exception:
            raise
        # Original __setattr__ ignored the seal and stored the value.
        _settings_tls.bypass = True
        try:
            if had_old:
                orig_setattr(self, name, old_value)
            else:
                try:
                    orig_delattr(self, name)
                except Exception:
                    try:
                        object.__delattr__(self, name)
                    except Exception:
                        pass
                keys = None
                try:
                    keys = object.__getattribute__(self, "_Settings__keys")
                except AttributeError:
                    keys = None
                if keys is not None:
                    try:
                        keys.remove(name)
                    except Exception:
                        pass
        finally:
            _settings_tls.bypass = False
        raise RuntimeError("settings has been sealed, cannot set %s" % name)

    def guarded_setattr(self, name, value):
        if _is_private(name) or getattr(_settings_tls, "bypass", False):
            return orig_setattr(self, name, value)
        with _settings_lock:
            if getattr(_settings_tls, "bypass", False):
                return orig_setattr(self, name, value)
            ensure_loaded(self)
            if not _is_sealed(self):
                object.__setattr__(self, "_Settings__sealed", True)
            return _reject_set(self, name, value)

    def guarded_delattr(self, name):
        if _is_private(name) or getattr(_settings_tls, "bypass", False):
            return orig_delattr(self, name)
        with _settings_lock:
            if getattr(_settings_tls, "bypass", False):
                return orig_delattr(self, name)
            ensure_loaded(self)
            if not _is_sealed(self):
                object.__setattr__(self, "_Settings__sealed", True)
            try:
                return orig_delattr(self, name)
            except Exception:
                raise
        raise RuntimeError("settings has been sealed, cannot delete %s" % name)

    cls._Settings__ensure_loaded = ensure_loaded
    cls.__setattr__ = guarded_setattr
    cls.__delattr__ = guarded_delattr
    type.__setattr__(cls, "_settings_write_guard_installed", True)


_install_settings_write_guard()


class modify_settings(object):
    """temporarily modify settings
    """

    def __init__(self, **kwargs):
        self.new_conf = kwargs
        self.old_conf = {}

    def _apply(self, assign):
        _settings_tls.bypass = True
        try:
            settings._Settings__sealed = False
            assign()
        finally:
            settings._Settings__sealed = True
            _settings_tls.bypass = False

    def __enter__(self):
        with _settings_lock:
            settings._Settings__ensure_loaded()  # ensure loaded
            _settings_prepared.add(id(settings))

            def assign():
                for key in self.new_conf:
                    self.old_conf[key] = getattr(settings, key, _NotExistedItem())
                    if isinstance(self.old_conf[key], _NotExistedItem):
                        settings._Settings__keys.add(key)
                    setattr(settings, key, self.new_conf[key])

            # Unseal only while this helper writes. The body and every later
