"""a module for unittest
"""
import os
import threading

from testbase.conf import settings


class _NotExistedItem(object):
    pass


# `_Settings.__getattribute__` loads and seals only after the first miss.
# `__setattr__` does not load, and may still replace a name that is already
# present. `modify_settings` drops the seal while it writes and used to leave
# it down, so a later assignment raised or was stored depending on history.
_lock = threading.RLock()
_tls = threading.local()
_loaded_ids = set()
_cls = type(settings)
_orig_setattr = _cls.__setattr__
_orig_delattr = _cls.__delattr__
_orig_ensure = _cls._Settings__ensure_loaded


def _is_private(name):
    return isinstance(name, str) and name.startswith("_Settings__")


def _is_sealed(obj):
    try:
        return bool(object.__getattribute__(obj, "_Settings__sealed"))
    except AttributeError:
        return False


def _set_sealed(obj, value):
    _orig_setattr(obj, "_Settings__sealed", bool(value))


def _wrapped_ensure(self):
    """Load at most once. `setattr` from the loader runs with depth > 0."""
    if id(self) in _loaded_ids or getattr(_tls, "depth", 0):
        return
    with _lock:
        if id(self) in _loaded_ids or getattr(_tls, "depth", 0):
            return
        _tls.depth = 1
        try:
            if not _is_sealed(self):
                result = _orig_ensure(self)
            else:
                result = None
            if not _is_sealed(self):
                _set_sealed(self, True)
        finally:
            _tls.depth = 0
        _loaded_ids.add(id(self))
        return result


def _reject(self, name, value):
    """Refuse a public write without keeping a value the original setter stored.

    Existing names are the case the original setter sometimes accepts. New
    names usually raise there; that error is propagated unchanged.
    """
    try:
        old = object.__getattribute__(self, name)
        existed = True
    except AttributeError:
        existed = False
        old = None
    try:
        _orig_setattr(self, name, value)
    except Exception:
        raise
    _tls.bypass = True
    try:
        _set_sealed(self, False)
        try:
            if existed:
                _orig_setattr(self, name, old)
            else:
                try:
                    _orig_delattr(self, name)
                except Exception:
                    pass
        finally:
            _set_sealed(self, True)
    finally:
        _tls.bypass = False
    raise RuntimeError("settings has been sealed, cannot set %s" % name)


def _guarded_setattr(self, name, value):
    if _is_private(name) or getattr(_tls, "depth", 0) or getattr(_tls, "bypass", False):
        return _orig_setattr(self, name, value)
    with _lock:
        if getattr(_tls, "depth", 0) or getattr(_tls, "bypass", False):
            return _orig_setattr(self, name, value)
        _wrapped_ensure(self)
        if _is_sealed(self):
            return _reject(self, name, value)
        return _orig_setattr(self, name, value)


_cls._Settings__ensure_loaded = _wrapped_ensure
_cls.__setattr__ = _guarded_setattr


class modify_settings(object):
    """temporarily modify settings
    """

    def __init__(self, **kwargs):
        self.new_conf = kwargs
        self.old_conf = {}

    def _run(self, func):
        # Hold the same lock as public writes so another thread cannot store
        # a value in this window. Bypass only applies to this thread.
        with _lock:
            _tls.bypass = True
            try:
                _set_sealed(settings, False)
                func()
            finally:
                _set_sealed(settings, True)
                _tls.bypass = False

    def __enter__(self):
        settings._Settings__ensure_loaded()  # ensure loaded
        for key in self.new_conf:
            self.old_conf[key] = getattr(settings, key, _NotExistedItem())
            if isinstance(self.old_conf[key], _NotExistedItem):
                settings._Settings__keys.add(key)

        def apply():
            for key in self.new_conf:
                setattr(settings, key, self.new_conf[key])

        self._run(apply)

    def __exit__(self, *args):
        def restore():
            for key in self.old_conf:
                old_value = self.old_conf[key]
                if isinstance(old_value, _NotExistedItem):
                    delattr(settings, key)
                    try:
                        settings._Settings__keys.remove(key)
                    except KeyError:
                        pass
                else:
                    setattr(settings, key, old_value)

        self._run(restore)


class modify_environ(object):
    """temporarily modify envrion
    """

    def __init__(self, **kwargs):
        self.new_conf = kwargs
        self.old_conf = {}

    def __enter__(self):
        for key in self.new_conf:
            self.old_conf[key] = os.environ.get(key, _NotExistedItem())
            os.environ[key] = self.new_conf[key]

    def __exit__(self, *args):
        for key in self.old_conf:
            old_value = self.old_conf[key]
            if isinstance(old_value, _NotExistedItem):
                del os.environ[key]
            else:
                os.environ[key] = old_value


class modify_attributes(object):
    """temporarily modify attributes
    """
    _lock = threading.Lock()

    def __init__(self, target, key_values):
        self._target = target
        self._old_values = {}
        self._new_values = key_values
        for key in key_values.keys():
            self._old_values[key] = getattr(target, key)

    def __enter__(self):
        self._lock.acquire()
        for key in self._new_values:
            setattr(self._target, key, self._new_values[key])

    def __exit__(self, *args):
        try:
            for key in self._old_values:
                setattr(self._target, key, self._old_values[key])
        finally:
            self._lock.release()
